insert into public.translations (locale, key, value) values
  ('pt-BR', 'site.notifications.empty', $json$"Convites e mudanças nas suas organizações aparecem aqui. Respostas prontas, perguntas do agente e limites do plano só aparecem no app."$json$::jsonb),
  ('en', 'site.notifications.empty', $json$"Invitations and changes in your organizations show up here. Finished answers, questions from the agent and plan limits only show up in the app."$json$::jsonb),
  ('es', 'site.notifications.empty', $json$"Aquí aparecen las invitaciones y los cambios en tus organizaciones. Las respuestas listas, las preguntas del agente y los límites del plan solo aparecen en la app."$json$::jsonb),
  ('fr', 'site.notifications.empty', $json$"Les invitations et les changements de vos organisations apparaissent ici. Les réponses prêtes, les questions de l'agent et les limites du forfait n'apparaissent que dans l'application."$json$::jsonb),
  ('de', 'site.notifications.empty', $json$"Einladungen und Änderungen in deinen Organisationen erscheinen hier. Fertige Antworten, Fragen des Agenten und Planlimits erscheinen nur in der App."$json$::jsonb),
  ('ru', 'site.notifications.empty', $json$"Здесь появляются приглашения и изменения в ваших организациях. Готовые ответы, вопросы агента и лимиты тарифа видны только в приложении."$json$::jsonb),
  ('zh-CN', 'site.notifications.empty', $json$"你所在组织的邀请和变更会显示在这里。完成的回答、智能体的提问和套餐额度只会显示在应用中。"$json$::jsonb),
  ('ja', 'site.notifications.empty', $json$"組織への招待や変更がここに表示されます。完了した回答、エージェントからの質問、プランの上限はアプリにのみ表示されます。"$json$::jsonb),
  ('hi', 'site.notifications.empty', $json$"आपके संगठनों के आमंत्रण और बदलाव यहाँ दिखते हैं। तैयार उत्तर, एजेंट के सवाल और प्लान की सीमाएँ केवल ऐप में दिखती हैं।"$json$::jsonb),
  ('ar', 'site.notifications.empty', $json$"تظهر هنا الدعوات والتغييرات في مؤسساتك. أما الردود الجاهزة وأسئلة الوكيل وحدود الخطة فتظهر في التطبيق فقط."$json$::jsonb),
  ('pt-BR', 'docs.notifications.title', $json$"Notificações"$json$::jsonb),
  ('en', 'docs.notifications.title', $json$"Notifications"$json$::jsonb),
  ('es', 'docs.notifications.title', $json$"Notificaciones"$json$::jsonb),
  ('fr', 'docs.notifications.title', $json$"Notifications"$json$::jsonb),
  ('de', 'docs.notifications.title', $json$"Benachrichtigungen"$json$::jsonb),
  ('ru', 'docs.notifications.title', $json$"Уведомления"$json$::jsonb),
  ('zh-CN', 'docs.notifications.title', $json$"通知"$json$::jsonb),
  ('ja', 'docs.notifications.title', $json$"通知"$json$::jsonb),
  ('hi', 'docs.notifications.title', $json$"सूचनाएँ"$json$::jsonb),
  ('ar', 'docs.notifications.title', $json$"الإشعارات"$json$::jsonb),
  ('pt-BR', 'docs.notifications.summary', $json$"O sino mostra o que acontece nas suas organizações (convites, mudanças de papel, remoções e mudanças de política) e, no app, respostas prontas, perguntas do agente, limites do plano e versões novas. O site tem o mesmo sino para as da conta, e ler uma de qualquer lado a marca como lida nos dois."$json$::jsonb),
  ('en', 'docs.notifications.summary', $json$"The bell shows what happens in your organizations (invitations, role changes, removals, policy changes) and, in the app, finished answers, questions from the agent, plan limits and new versions. The site has the same bell for the account ones, and reading one on either side marks it read on both."$json$::jsonb),
  ('es', 'docs.notifications.summary', $json$"La campana muestra lo que ocurre en tus organizaciones (invitaciones, cambios de rol, expulsiones y cambios de política) y, en la app, respuestas listas, preguntas del agente, límites del plan y versiones nuevas. El sitio tiene la misma campana para las de la cuenta, y leer una en cualquiera de los dos la marca como leída en ambos."$json$::jsonb),
  ('fr', 'docs.notifications.summary', $json$"La cloche montre ce qui se passe dans vos organisations (invitations, changements de rôle, retraits, changements de politique) et, dans l'application, les réponses prêtes, les questions de l'agent, les limites du forfait et les nouvelles versions. Le site a la même cloche pour celles du compte, et en lire une d'un côté la marque comme lue des deux côtés."$json$::jsonb),
  ('de', 'docs.notifications.summary', $json$"Die Glocke zeigt, was in deinen Organisationen passiert (Einladungen, Rollenwechsel, Entfernungen, Richtlinienänderungen) und in der App außerdem fertige Antworten, Fragen des Agenten, Planlimits und neue Versionen. Die Website hat dieselbe Glocke für die Konto-Benachrichtigungen, und wer eine auf einer Seite liest, markiert sie auf beiden als gelesen."$json$::jsonb),
  ('ru', 'docs.notifications.summary', $json$"Колокольчик показывает, что происходит в ваших организациях (приглашения, смена ролей, удаление, изменение политики), а в приложении ещё и готовые ответы, вопросы агента, лимиты тарифа и новые версии. На сайте тот же колокольчик для уведомлений аккаунта, и прочитанное с одной стороны отмечается прочитанным и с другой."$json$::jsonb),
  ('zh-CN', 'docs.notifications.summary', $json$"铃铛显示你所在组织发生的事（邀请、角色变更、被移除、策略变更），在应用中还包括完成的回答、智能体的提问、套餐额度和新版本。网站为账户类通知提供同样的铃铛，在任一端阅读都会在两端标记为已读。"$json$::jsonb),
  ('ja', 'docs.notifications.summary', $json$"ベルには、組織で起きたこと（招待、ロールの変更、削除、ポリシーの変更）が表示され、アプリでは完了した回答、エージェントからの質問、プランの上限、新バージョンも表示されます。サイトにもアカウントの通知用に同じベルがあり、どちらで読んでも両方で既読になります。"$json$::jsonb),
  ('hi', 'docs.notifications.summary', $json$"घंटी आपके संगठनों में हुई बातें दिखाती है (आमंत्रण, भूमिका में बदलाव, हटाया जाना, नीति में बदलाव) और ऐप में तैयार उत्तर, एजेंट के सवाल, प्लान की सीमाएँ और नए संस्करण भी। साइट पर खाते की सूचनाओं के लिए वही घंटी है, और किसी एक तरफ़ पढ़ने पर वह दोनों जगह पढ़ी हुई हो जाती है।"$json$::jsonb),
  ('ar', 'docs.notifications.summary', $json$"يعرض الجرس ما يحدث في مؤسساتك (الدعوات وتغيّر الأدوار والإزالة وتغيّر السياسة)، وفي التطبيق أيضًا الردود الجاهزة وأسئلة الوكيل وحدود الخطة والإصدارات الجديدة. للموقع الجرس نفسه لإشعارات الحساب، وقراءة أحدها في أي جهة تضعه كمقروء في الجهتين."$json$::jsonb),
  ('pt-BR', 'docs.notifications.usage', $json$"No app, o sino fica à direita do logotipo na lateral; no Ctrl+K, escolha Notificações para abri-lo. No site, ele fica na barra de cima assim que você entra. Clique numa notificação para ir à organização; o convite pode ser aceito ou recusado ali mesmo, na lista. Marque todas como lidas ou limpe as lidas pelo painel. O site atualiza a lista a cada minuto e quando você a abre. Respostas, perguntas e limites só existem no app, no aparelho em que aconteceram."$json$::jsonb),
  ('en', 'docs.notifications.usage', $json$"In the app the bell sits to the right of the logo in the sidebar; in Ctrl+K choose Notifications to open it. On the site it sits in the top bar once you are signed in. Click a notification to go to its organization; an invitation can be accepted or declined right in the list. Mark all as read, or clear the read ones, from the panel. The site refreshes the list every minute and when you open it. Answers, questions and limits only exist in the app, on the device where they happened."$json$::jsonb),
  ('es', 'docs.notifications.usage', $json$"En la app, la campana está a la derecha del logotipo en la barra lateral; en Ctrl+K elige Notificaciones para abrirla. En el sitio está en la barra superior en cuanto inicias sesión. Haz clic en una notificación para ir a su organización; la invitación se puede aceptar o rechazar ahí mismo, en la lista. Marca todas como leídas o limpia las leídas desde el panel. El sitio actualiza la lista cada minuto y al abrirla. Las respuestas, preguntas y límites solo existen en la app, en el dispositivo donde ocurrieron."$json$::jsonb),
  ('fr', 'docs.notifications.usage', $json$"Dans l'application, la cloche est à droite du logo dans la barre latérale ; dans Ctrl+K, choisissez Notifications pour l'ouvrir. Sur le site, elle se trouve dans la barre du haut dès que vous êtes connecté. Cliquez sur une notification pour aller à son organisation ; une invitation peut être acceptée ou refusée directement dans la liste. Marquez tout comme lu ou effacez les lues depuis le panneau. Le site actualise la liste chaque minute et à son ouverture. Les réponses, questions et limites n'existent que dans l'application, sur l'appareil où elles se sont produites."$json$::jsonb),
  ('de', 'docs.notifications.usage', $json$"In der App sitzt die Glocke rechts neben dem Logo in der Seitenleiste; in Strg+K öffnest du sie mit Benachrichtigungen. Auf der Website sitzt sie in der oberen Leiste, sobald du angemeldet bist. Klicke auf eine Benachrichtigung, um zur Organisation zu gelangen; eine Einladung kannst du direkt in der Liste annehmen oder ablehnen. Alle als gelesen markieren oder gelesene löschen geht im Panel. Die Website aktualisiert die Liste jede Minute und beim Öffnen. Antworten, Fragen und Limits gibt es nur in der App, auf dem Gerät, auf dem sie passiert sind."$json$::jsonb),
  ('ru', 'docs.notifications.usage', $json$"В приложении колокольчик находится справа от логотипа в боковой панели; в Ctrl+K выберите «Уведомления», чтобы открыть его. На сайте он находится в верхней панели после входа. Нажмите на уведомление, чтобы перейти к его организации; приглашение можно принять или отклонить прямо в списке. Отметить всё прочитанным или очистить прочитанные можно в панели. Сайт обновляет список каждую минуту и при открытии. Ответы, вопросы и лимиты есть только в приложении, на устройстве, где они произошли."$json$::jsonb),
  ('zh-CN', 'docs.notifications.usage', $json$"在应用中，铃铛位于侧边栏 logo 右侧；在 Ctrl+K 中选择“通知”即可打开。在网站上，登录后它位于顶部栏。点击通知可前往对应的组织；邀请可直接在列表中接受或拒绝。可在面板中将全部标为已读或清除已读通知。网站每分钟以及打开列表时都会刷新。回答、提问和额度提醒只存在于应用中，只在发生它们的设备上。"$json$::jsonb),
  ('ja', 'docs.notifications.usage', $json$"アプリでは、ベルはサイドバーのロゴの右にあります。Ctrl+K で「通知」を選ぶと開きます。サイトでは、サインインするとトップバーに表示されます。通知をクリックするとその組織に移動し、招待はリストの中でそのまま承諾または辞退できます。パネルから、すべて既読にしたり既読を消去したりできます。サイトはリストを 1 分ごと、および開いたときに更新します。回答、質問、上限の通知はアプリだけにあり、発生した端末にのみ表示されます。"$json$::jsonb),
  ('hi', 'docs.notifications.usage', $json$"ऐप में घंटी साइडबार में लोगो के दाईं ओर है; Ctrl+K में सूचनाएँ चुनकर उसे खोलें। साइट पर साइन इन करते ही वह ऊपर की पट्टी में दिखती है। किसी सूचना पर क्लिक करके उसके संगठन पर जाएँ; आमंत्रण सूची में ही स्वीकार या अस्वीकार किया जा सकता है। पैनल से सभी को पढ़ा हुआ चिह्नित करें या पढ़ी हुई साफ़ करें। साइट सूची को हर मिनट और खोलने पर ताज़ा करती है। उत्तर, सवाल और सीमाएँ केवल ऐप में होती हैं, उसी डिवाइस पर जहाँ वे हुईं।"$json$::jsonb),
  ('ar', 'docs.notifications.usage', $json$"في التطبيق يقع الجرس إلى يمين الشعار في الشريط الجانبي؛ وفي Ctrl+K اختر الإشعارات لفتحه. وفي الموقع يظهر في الشريط العلوي بمجرد تسجيل الدخول. انقر على إشعار للانتقال إلى مؤسسته؛ ويمكن قبول الدعوة أو رفضها من القائمة مباشرة. علّم الكل كمقروء أو امسح المقروء من اللوحة. يحدّث الموقع القائمة كل دقيقة وعند فتحها. الردود والأسئلة والحدود موجودة في التطبيق فقط، على الجهاز الذي حدثت عليه."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.siteNotifications.title', $json$"Notificações também no site"$json$::jsonb),
  ('en', 'whatsNew.item.siteNotifications.title', $json$"Notifications on the site too"$json$::jsonb),
  ('es', 'whatsNew.item.siteNotifications.title', $json$"Notificaciones también en el sitio"$json$::jsonb),
  ('fr', 'whatsNew.item.siteNotifications.title', $json$"Notifications aussi sur le site"$json$::jsonb),
  ('de', 'whatsNew.item.siteNotifications.title', $json$"Benachrichtigungen jetzt auch auf der Website"$json$::jsonb),
  ('ru', 'whatsNew.item.siteNotifications.title', $json$"Уведомления теперь и на сайте"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.siteNotifications.title', $json$"网站也有通知了"$json$::jsonb),
  ('ja', 'whatsNew.item.siteNotifications.title', $json$"サイトでも通知が届きます"$json$::jsonb),
  ('hi', 'whatsNew.item.siteNotifications.title', $json$"अब साइट पर भी सूचनाएँ"$json$::jsonb),
  ('ar', 'whatsNew.item.siteNotifications.title', $json$"الإشعارات متاحة الآن في الموقع أيضًا"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.siteNotifications.detail', $json$"O site ganhou o mesmo sino do app, na barra de cima: convites e mudanças nas suas organizações aparecem ali, o convite pode ser aceito ou recusado na lista, e ler uma notificação a marca como lida no app também. Respostas, perguntas do agente e limites do plano continuam só no app."$json$::jsonb),
  ('en', 'whatsNew.item.siteNotifications.detail', $json$"The site now has the same bell as the app, in the top bar: invitations and changes in your organizations show up there, an invitation can be accepted or declined in the list, and reading a notification marks it read in the app too. Answers, questions from the agent and plan limits stay in the app only."$json$::jsonb),
  ('es', 'whatsNew.item.siteNotifications.detail', $json$"El sitio tiene ahora la misma campana que la app, en la barra superior: ahí aparecen las invitaciones y los cambios en tus organizaciones, la invitación se puede aceptar o rechazar en la lista, y leer una notificación la marca como leída también en la app. Las respuestas, las preguntas del agente y los límites del plan siguen solo en la app."$json$::jsonb),
  ('fr', 'whatsNew.item.siteNotifications.detail', $json$"Le site a désormais la même cloche que l'application, dans la barre du haut : les invitations et les changements de vos organisations y apparaissent, l'invitation peut être acceptée ou refusée dans la liste, et lire une notification la marque aussi comme lue dans l'application. Les réponses, les questions de l'agent et les limites du forfait restent uniquement dans l'application."$json$::jsonb),
  ('de', 'whatsNew.item.siteNotifications.detail', $json$"Die Website hat jetzt dieselbe Glocke wie die App, in der oberen Leiste: Einladungen und Änderungen in deinen Organisationen erscheinen dort, eine Einladung lässt sich in der Liste annehmen oder ablehnen, und wer eine Benachrichtigung liest, markiert sie auch in der App als gelesen. Antworten, Fragen des Agenten und Planlimits bleiben nur in der App."$json$::jsonb),
  ('ru', 'whatsNew.item.siteNotifications.detail', $json$"На сайте появился тот же колокольчик, что и в приложении, в верхней панели: там видны приглашения и изменения в ваших организациях, приглашение можно принять или отклонить прямо в списке, а прочитанное уведомление отмечается прочитанным и в приложении. Ответы, вопросы агента и лимиты тарифа остаются только в приложении."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.siteNotifications.detail', $json$"网站现在在顶部栏有了与应用相同的铃铛：你所在组织的邀请和变更会显示在那里，可直接在列表中接受或拒绝邀请，阅读通知后在应用中也会标为已读。回答、智能体的提问和套餐额度仍只在应用中显示。"$json$::jsonb),
  ('ja', 'whatsNew.item.siteNotifications.detail', $json$"サイトのトップバーに、アプリと同じベルが付きました。組織への招待や変更がそこに表示され、招待はリストの中で承諾または辞退でき、通知を読むとアプリでも既読になります。回答、エージェントからの質問、プランの上限はこれまでどおりアプリにだけ表示されます。"$json$::jsonb),
  ('hi', 'whatsNew.item.siteNotifications.detail', $json$"साइट की ऊपरी पट्टी में अब ऐप जैसी ही घंटी है: आपके संगठनों के आमंत्रण और बदलाव वहाँ दिखते हैं, आमंत्रण सूची में ही स्वीकार या अस्वीकार किया जा सकता है, और सूचना पढ़ने पर वह ऐप में भी पढ़ी हुई हो जाती है। उत्तर, एजेंट के सवाल और प्लान की सीमाएँ अब भी केवल ऐप में हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.siteNotifications.detail', $json$"صار للموقع الجرس نفسه الموجود في التطبيق، في الشريط العلوي: تظهر هناك الدعوات والتغييرات في مؤسساتك، ويمكن قبول الدعوة أو رفضها من القائمة، وقراءة إشعار تضعه كمقروء في التطبيق أيضًا. أما الردود وأسئلة الوكيل وحدود الخطة فتبقى في التطبيق فقط."$json$::jsonb)
